#!/usr/bin/env python3
"""Preregistered H1 probe: Hermite tails of arctan and its derivative."""

from __future__ import annotations

import csv
import json
import math
from pathlib import Path
import sys

import numpy as np
from scipy.special import roots_hermitenorm


sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)
ORDERS = (512, 1024, 2048)
K_MAX = 240
ABS_AGREE = 1e-13
REL_AGREE = 1e-6


def coefficients(quadrature_order: int, k_max: int) -> dict[str, np.ndarray]:
    nodes, weights = roots_hermitenorm(quadrature_order)
    weights = weights / math.sqrt(2.0 * math.pi)
    functions = {
        "arctan": np.arctan(nodes),
        "d": 1.0 / (1.0 + nodes * nodes),
    }
    result = {name: np.empty(k_max + 1) for name in functions}

    h_prev = np.ones_like(nodes)
    for name, values in functions.items():
        result[name][0] = np.dot(weights, values * h_prev)
    if k_max == 0:
        return result

    h_curr = nodes.copy()
    for name, values in functions.items():
        result[name][1] = np.dot(weights, values * h_curr)

    for k in range(1, k_max):
        h_next = (nodes * h_curr - math.sqrt(k) * h_prev) / math.sqrt(k + 1)
        for name, values in functions.items():
            result[name][k + 1] = np.dot(weights, values * h_next)
        h_prev, h_curr = h_curr, h_next
    return result


def reliable_mask(values_a: np.ndarray, values_b: np.ndarray, parity: int) -> np.ndarray:
    scale = np.maximum(np.maximum(np.abs(values_a), np.abs(values_b)), 1e-300)
    agree = (np.abs(values_a - values_b) <= ABS_AGREE) | (
        np.abs(values_a - values_b) / scale <= REL_AGREE
    )
    k = np.arange(values_a.size)
    correct_parity = (k % 2) == parity
    above_floor = np.maximum(np.abs(values_a), np.abs(values_b)) >= 3e-14
    return agree & correct_parity & above_floor


def regression(k: np.ndarray, log_abs_c: np.ndarray, model: str) -> dict[str, object]:
    if model == "root":
        design = np.column_stack([np.ones_like(k), np.sqrt(k), np.log(k)])
    elif model == "linear":
        design = np.column_stack([np.ones_like(k), k, np.log(k)])
    else:
        raise ValueError(model)
    coef, *_ = np.linalg.lstsq(design, log_abs_c, rcond=None)
    pred = design @ coef
    rmse = float(np.sqrt(np.mean((pred - log_abs_c) ** 2)))
    return {"coefficients": coef.tolist(), "rmse": rmse}


def fit_with_holdout(k: np.ndarray, c: np.ndarray) -> dict[str, object]:
    order = np.argsort(k)
    k = k[order]
    y = np.log(np.abs(c[order]))
    split = max(4, len(k) // 2)
    k_fit, y_fit = k[:split], y[:split]
    k_val, y_val = k[split:], y[split:]
    report: dict[str, object] = {
        "fit_k": [int(k_fit[0]), int(k_fit[-1])],
        "validation_k": [int(k_val[0]), int(k_val[-1])] if len(k_val) else None,
    }
    for model in ("root", "linear"):
        fit = regression(k_fit, y_fit, model)
        coef = np.asarray(fit["coefficients"])
        if model == "root":
            val_design = np.column_stack(
                [np.ones_like(k_val), np.sqrt(k_val), np.log(k_val)]
            )
        else:
            val_design = np.column_stack([np.ones_like(k_val), k_val, np.log(k_val)])
        validation_rmse = (
            float(np.sqrt(np.mean((val_design @ coef - y_val) ** 2)))
            if len(k_val)
            else None
        )
        report[model] = {**fit, "validation_rmse": validation_rmse}
    return report


def main() -> None:
    OUT = PATHS.parse(output_relative="experiments/outputs/hermite_tail").output_dir
    OUT.mkdir(parents=True, exist_ok=True)
    all_values = {order: coefficients(order, K_MAX) for order in ORDERS}

    with (OUT / "coefficients.csv").open("w", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(["function", "k", *[f"q{q}" for q in ORDERS]])
        for name in ("arctan", "d"):
            for k in range(K_MAX + 1):
                writer.writerow(
                    [name, k, *[f"{all_values[q][name][k]:.18e}" for q in ORDERS]]
                )

    q_a, q_b = ORDERS[-2:]
    summary: dict[str, object] = {
        "quadrature_orders": list(ORDERS),
        "k_max": K_MAX,
        "agreement": {"absolute": ABS_AGREE, "relative": REL_AGREE},
    }
    for name, parity in (("arctan", 1), ("d", 0)):
        a = all_values[q_a][name]
        b = all_values[q_b][name]
        mask = reliable_mask(a, b, parity)
        reliable_k = np.flatnonzero(mask)
        # Exclude the first few modes; the question concerns asymptotic decay.
        reliable_k = reliable_k[reliable_k >= 9]
        summary[name] = {
            "reliable_count": int(len(reliable_k)),
            "reliable_k_min": int(reliable_k[0]) if len(reliable_k) else None,
            "reliable_k_max": int(reliable_k[-1]) if len(reliable_k) else None,
            "parity_leak_max": float(
                np.max(np.abs(b[np.arange(K_MAX + 1) % 2 != parity]))
            ),
            "fits": fit_with_holdout(reliable_k, b[reliable_k])
            if len(reliable_k) >= 10
            else None,
        }

    (OUT / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Preregistered K0 probe: Gaussian-seed obstruction to analytic time norms."""

from __future__ import annotations

import csv
import json
import math
from pathlib import Path
import sys

import numpy as np
from scipy.special import gammaln, roots_hermitenorm


sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)
K_MAX = 80
QUADRATURE_ORDERS = (256, 384)


def convolution_at(a: list[np.ndarray], b: list[np.ndarray], k: int) -> np.ndarray:
    return sum((a[i] * b[k - i] for i in range(k + 1)), start=np.zeros_like(a[0]))


def reciprocal_coefficient(
    denominator: list[np.ndarray], reciprocal: list[np.ndarray], k: int
) -> np.ndarray:
    if k == 0:
        return 1.0 / denominator[0]
    accumulated = sum(
        (denominator[i] * reciprocal[k - i] for i in range(1, k + 1)),
        start=np.zeros_like(denominator[0]),
    )
    return -accumulated / denominator[0]


def atan_coefficient(
    argument: list[np.ndarray], derivative_gate: list[np.ndarray], k: int
) -> np.ndarray:
    if k == 0:
        return np.arctan(argument[0])
    accumulated = sum(
        (derivative_gate[i] * (k - i) * argument[k - i] for i in range(k)),
        start=np.zeros_like(argument[0]),
    )
    return accumulated / k


def scalar_series(a0: np.ndarray, k_max: int) -> dict[str, object]:
    zero = np.zeros_like(a0)
    a = [a0.copy()]
    u = [zero.copy()]
    d: list[np.ndarray] = []
    x: list[np.ndarray] = []
    u_velocity: list[np.ndarray] = []
    denominator: list[np.ndarray] = []

    for k in range(k_max + 1):
        u_square = convolution_at(u, u, k)
        denominator.append(u_square + (1.0 if k == 0 else 0.0))
        d.append(reciprocal_coefficient(denominator, d, k))
        x.append(atan_coefficient(u, d, k))
        u_velocity.append(convolution_at(a, d, k))
        if k < k_max:
            a.append(x[k] / (k + 1))
            u.append(u_velocity[k] / (k + 1))

    f = [convolution_at(a, x, k) for k in range(k_max + 1)]
    x_square = [convolution_at(x, x, k) for k in range(k_max + 1)]
    velocity_square = [
        convolution_at(u_velocity, u_velocity, k) for k in range(k_max + 1)
    ]
    kernel = [x_square[k] + velocity_square[k] for k in range(k_max + 1)]
    gradient_residual = max(
        float(
            np.max(np.abs((k + 1) * f[k + 1] - kernel[k]))
            / (1.0 + np.max(np.abs(kernel[k])))
        )
        for k in range(k_max)
    )
    return {
        "a": a,
        "u": u,
        "d": d,
        "x": x,
        "u_velocity": u_velocity,
        "f": f,
        "kernel": kernel,
        "gradient_residual": gradient_residual,
    }


def inverse_leading_series(k_max: int) -> np.ndarray:
    # psi solves psi'=1/(1+psi^2), psi(0)=0.  The leading kernel is psi'^2.
    zero = np.zeros(1)
    psi = [zero.copy()]
    d: list[np.ndarray] = []
    denominator: list[np.ndarray] = []
    for k in range(k_max + 1):
        psi_square = convolution_at(psi, psi, k)
        denominator.append(psi_square + (1.0 if k == 0 else 0.0))
        d.append(reciprocal_coefficient(denominator, d, k))
        if k < k_max:
            psi.append(d[k] / (k + 1))
    return np.array([float(convolution_at(d, d, k)[0]) for k in range(k_max + 1)])


def normalized_hermite(nodes: np.ndarray, k_max: int) -> list[np.ndarray]:
    values = [np.ones_like(nodes), nodes.copy()]
    for k in range(1, k_max):
        values.append(
            (nodes * values[k] - math.sqrt(k) * values[k - 1]) / math.sqrt(k + 1)
        )
    return values[: k_max + 1]


def run_quadrature(order: int, leading: np.ndarray) -> dict[str, object]:
    nodes, weights = roots_hermitenorm(order)
    weights = weights / math.sqrt(2.0 * math.pi)
    jet = scalar_series(nodes, K_MAX)
    hermite = normalized_hermite(nodes, K_MAX + 2)
    signed = np.empty(K_MAX + 1)
    l2 = np.empty(K_MAX + 1)
    extracted_leading = np.empty(K_MAX + 1)
    for k, coefficient in enumerate(jet["kernel"]):
        signed[k] = np.dot(weights, coefficient)
        l2[k] = math.sqrt(max(0.0, np.dot(weights, coefficient * coefficient)))
        projection = np.dot(weights, coefficient * hermite[k + 2])
        extracted_leading[k] = projection * math.exp(-0.5 * gammaln(k + 3))
    return {
        "signed": signed,
        "l2": l2,
        "extracted_leading": extracted_leading,
        "leading": leading,
        "gradient_residual": jet["gradient_residual"],
    }


def positive_root(value: float, k: int) -> float:
    if k == 0 or value == 0.0:
        return 0.0
    return float(abs(value) ** (1.0 / k))


def main() -> None:
    OUT = PATHS.parse(output_relative="experiments/outputs/l1_koopman_obstruction_v2").output_dir
    OUT.mkdir(parents=True, exist_ok=True)
    leading = inverse_leading_series(K_MAX)
    results = {order: run_quadrature(order, leading) for order in QUADRATURE_ORDERS}

    with (OUT / "coefficients.csv").open("w", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(
            [
                "k",
                "leading_inverse_series",
                *[
                    field
                    for order in QUADRATURE_ORDERS
                    for field in (
                        f"signed_q{order}",
                        f"l2_q{order}",
                        f"extracted_leading_q{order}",
                    )
                ],
            ]
        )
        for k in range(K_MAX + 1):
            row: list[object] = [k, f"{leading[k]:.18e}"]
            for order in QUADRATURE_ORDERS:
                row.extend(
                    [
                        f"{results[order]['signed'][k]:.18e}",
                        f"{results[order]['l2'][k]:.18e}",
                        f"{results[order]['extracted_leading'][k]:.18e}",
                    ]
                )
            writer.writerow(row)

    high = results[QUADRATURE_ORDERS[-1]]
    selected = {}
    for k in range(10, K_MAX + 1, 10):
        selected[str(k)] = {
            "signed_root": positive_root(float(high["signed"][k]), k),
            "l2_root": positive_root(float(high["l2"][k]), k),
            "leading_root": positive_root(float(leading[k]), k),
            "leading_relative_error": float(
                abs(high["extracted_leading"][k] - leading[k])
                / max(abs(leading[k]), 1e-300)
            ),
        }

    low, high_order = QUADRATURE_ORDERS
    reliable = []
    for k in range(K_MAX + 1):
        values = (results[low]["l2"][k], results[high_order]["l2"][k])
        scale = max(abs(values[0]), abs(values[1]), 1e-300)
        if all(np.isfinite(value) for value in values) and abs(values[0] - values[1]) / scale < 1e-8:
            reliable.append(k)

    report = {
        "k_max": K_MAX,
        "quadrature_orders": list(QUADRATURE_ORDERS),
        "gradient_identity_residuals": {
            str(order): results[order]["gradient_residual"]
            for order in QUADRATURE_ORDERS
        },
        "largest_l2_agreement_order": max(reliable),
        "selected_even_orders": selected,
    }
    (OUT / "summary.json").write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()

