"""Exact six-point proof of the primary explicit-Q0 coefficient powers.

The independent compiler accepts exact rational Q0 but does not serialize it
symbolically.  Both routes have explicit Q0 degree at most k in D^k f when
layer moments are treated as formal atoms.  Equality at six distinct points
therefore proves the complete A/B/C coefficient polynomials (bounds 1/3/5).
"""

from __future__ import annotations

from fractions import Fraction
import gc
import json
from pathlib import Path

from ..independent.depth_factored import compile_depth_factored, expand_expression
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)


HERE = Path(__file__).resolve().parent
PRIMARY = HERE.parent / "primary"
INDEPENDENT = HERE.parent / "independent"
POINTS = tuple(Fraction(value, 2) for value in (1, 2, 3, 4, 5, 6))
HOLDOUT = Fraction(7, 2)
DEGREE_BOUNDS = {"A": 1, "B": 3, "C": 5}


def primary_graded(depth: int, input_dir=None):
    path = (input_dir or PATHS.generated / "depth_order5/primary") / f"H{depth}_LAYER_TAGGED_COEFFICIENTS.json"
    payload = json.loads(path.read_text())
    answer = {}
    observed = {}
    for root in "ABC":
        mapping = {}
        maximum = 0
        for atoms, coefficient_text in payload["roots"][root]:
            degree = atoms.count("Q0")
            activation = tuple(sorted(atom for atom in atoms if atom != "Q0"))
            key = (activation, degree)
            mapping[key] = mapping.get(key, Fraction(0)) + Fraction(coefficient_text)
            maximum = max(maximum, degree)
        mapping = {key: value for key, value in mapping.items() if value}
        if maximum > DEGREE_BOUNDS[root]:
            raise AssertionError((depth, root, maximum, DEGREE_BOUNDS[root]))
        answer[root] = mapping
        observed[root] = maximum
    return answer, observed


def specialize(graded, point: Fraction):
    answer = {}
    for root in "ABC":
        mapping = {}
        for (atoms, degree), coefficient in graded[root].items():
            mapping[atoms] = mapping.get(atoms, Fraction(0)) + coefficient * point**degree
        answer[root] = {key: value for key, value in mapping.items() if value}
    return answer


def independent_map(depth: int, point: Fraction, input_dir=None):
    # Reuse the separately frozen Q0=1 map; compile every other point afresh.
    if point == 1:
        payload = json.loads(
            ((input_dir or PATHS.generated / "depth_order5/independent") / f"H{depth}_TAGGED_COEFFICIENT_MAP.json").read_text()
        )
        return {
            root: {
                tuple(sorted(record["atoms"])): Fraction(record["coefficient"])
                for record in payload[root]
            }
            for root in "ABC"
        }
    result = compile_depth_factored(depth, q0=point, unit_gram=False)
    return {
        "A": expand_expression(result.A),
        "B": expand_expression(result.B),
        "C": expand_expression(result.C),
    }


def compare(left, right):
    report = {}
    for root in "ABC":
        mismatch_count = 0
        first = []
        for atoms in set(left[root]) | set(right[root]):
            if left[root].get(atoms, 0) != right[root].get(atoms, 0):
                mismatch_count += 1
                if len(first) < 10:
                    first.append(
                        {
                            "atoms": list(atoms),
                            "primary": str(left[root].get(atoms, 0)),
                            "independent": str(right[root].get(atoms, 0)),
                        }
                    )
        report[root] = {
            "primary_terms": len(left[root]),
            "independent_terms": len(right[root]),
            "discrepancy_count": mismatch_count,
            "first_discrepancies": first,
        }
    return report


def main() -> None:
    args = PATHS.parse(inputs=True, input_relative="depth_order5")
    full_report = {
        "method": (
            "exact rational specialization at six distinct points; explicit "
            "degree bounds A/B/C<=1/3/5; seventh point unused holdout"
        ),
        "degree_proof": (
            "With layer moments formal, explicit Q0 occurs only in zdot1=Q0*b1. "
            "Each directional/time derivative inserts at most one vector-field "
            "factor, so deg_Q0 D^k f<=k. Wick, Stein, expectation, and equality "
            "partitioning preserve total Taylor order and cannot raise the bound."
        ),
        "degree_bounds": DEGREE_BOUNDS,
        "interpolation_points": [str(point) for point in POINTS],
        "holdout_point": str(HOLDOUT),
        "depths": {},
    }
    passed = True
    for depth in (3, 4):
        graded, observed = primary_graded(depth, args.input_dir / "primary")
        depth_report = {"primary_observed_degrees": observed, "points": {}}
        for point in POINTS + (HOLDOUT,):
            primary = specialize(graded, point)
            independent = independent_map(depth, point, args.input_dir / "independent")
            point_report = compare(primary, independent)
            depth_report["points"][str(point)] = point_report
            discrepancies = {root: point_report[root]["discrepancy_count"] for root in "ABC"}
            print(f"H={depth} Q0={point}: {discrepancies}", flush=True)
            if any(discrepancies.values()):
                passed = False
            del primary, independent
            gc.collect()
        full_report["depths"][str(depth)] = depth_report
        del graded
        gc.collect()
    full_report["pass"] = passed
    args.output_dir.mkdir(parents=True, exist_ok=True)
    output = args.output_dir / "SYMBOLIC_Q0_AUDIT.json"
    output.write_text(json.dumps(full_report, indent=2, sort_keys=True) + "\n")
    print(output)
    if not passed:
        raise SystemExit("symbolic Q0 audit failed")


if __name__ == "__main__":
    main()

"""Hostile literal comparison of the two independently frozen depth maps."""

from __future__ import annotations

from fractions import Fraction
from hashlib import sha256
import json
from pathlib import Path
import re
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[4]))
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)


HERE = Path(__file__).resolve().parent
BASE = HERE.parent
PRIMARY = BASE / "primary"
INDEPENDENT = BASE / "independent"
PRIMARY_MANIFEST = PRIMARY / "PRIMARY_FREEZE_MANIFEST.json"
INDEPENDENT_MANIFEST = INDEPENDENT / "FROZEN_MANIFEST.json"


def _artifact_path(directory: Path, data_directory: Path, name: str) -> Path:
    if Path(name).name != name:
        raise ValueError(f"expected a local artifact name: {name}")
    if name.endswith(("_COEFFICIENTS.json", "_COEFFICIENT_MAP.json")):
        return data_directory / name
    # Exact formula source and fixed freeze evidence were intentionally retained
    # with source. Prefer an explicit input copy when one was supplied.
    candidate = data_directory / name
    return candidate if candidate.is_file() else directory / name


def _verify_manifest(directory: Path, manifest_path: Path, hash_path: Path, *, data_directory: Path) -> dict:
    manifest_bytes = manifest_path.read_bytes()
    declared = hash_path.read_text().split()[0]
    actual = sha256(manifest_bytes).hexdigest()
    if actual != declared:
        raise AssertionError((manifest_path, declared, actual))
    manifest = json.loads(manifest_bytes)
    for record in manifest["artifacts"].values():
        # Primary records are direct; independent records contain dag/expanded/text.
        if "sha256" in record:
            records = [record]
        else:
            records = [
                value
                for value in record.values()
                if isinstance(value, dict) and "file" in value and "sha256" in value
            ]
        for artifact in records:
            if not artifact.get("file"):
                # Primary key itself is the filename.
                continue
            path = _artifact_path(directory, data_directory, artifact["file"])
            digest = sha256(path.read_bytes()).hexdigest()
            if digest != artifact["sha256"]:
                raise AssertionError((path, artifact["sha256"], digest))
    if directory == PRIMARY:
        for filename, record in manifest["artifacts"].items():
            path = _artifact_path(directory, data_directory, filename)
            digest = sha256(path.read_bytes()).hexdigest()
            if digest != record["sha256"]:
                raise AssertionError((path, record["sha256"], digest))
            if path.stat().st_size != record["bytes"]:
                raise AssertionError((path, record["bytes"], path.stat().st_size))
    return manifest


def _atom_derivative(atom: str, depth: int, unit: bool) -> int:
    pattern = r"M_([0-9]{6})" if unit else rf"L([1-{depth}])_([0-9]{{6}})"
    match = re.fullmatch(pattern, atom)
    if not match:
        raise AssertionError((atom, depth, unit))
    digits = match.group(1) if unit else match.group(2)
    return max(
        (index for index, multiplicity in enumerate(digits) if multiplicity != "0"),
        default=0,
    )


def _primary_map(path: Path, depth: int, unit: bool):
    payload = json.loads(path.read_text())
    result = {}
    maxima = {}
    for root in "ABC":
        polynomial = {}
        maximum = 0
        for atoms, coefficient_text in payload["roots"][root]:
            activation_atoms = []
            for atom in atoms:
                if atom == "Q0":
                    if unit:
                        raise AssertionError("Q0 survived in the primary unit map")
                    continue  # common tagged quotient Q0=1
                maximum = max(maximum, _atom_derivative(atom, depth, unit))
                activation_atoms.append(atom)
            key = tuple(sorted(activation_atoms))
            polynomial[key] = polynomial.get(key, Fraction(0)) + Fraction(coefficient_text)
        result[root] = {key: value for key, value in polynomial.items() if value}
        maxima[root] = maximum
    return result, maxima


def _independent_map(path: Path, depth: int, unit: bool):
    payload = json.loads(path.read_text())
    if payload["Q0"] != "1" or payload["unit_gram"] is not unit:
        raise AssertionError((path, payload["Q0"], payload["unit_gram"]))
    result = {}
    maxima = {}
    for root in "ABC":
        polynomial = {}
        maximum = 0
        for record in payload[root]:
            atoms = tuple(sorted(record["atoms"]))
            for atom in atoms:
                maximum = max(maximum, _atom_derivative(atom, depth, unit))
            if atoms in polynomial:
                raise AssertionError((path, root, "duplicate", atoms))
            polynomial[atoms] = Fraction(record["coefficient"])
        result[root] = {key: value for key, value in polynomial.items() if value}
        maxima[root] = maximum
    return result, maxima


def main() -> None:
    args = PATHS.parse(inputs=True, input_relative="depth_order5")
    primary_manifest = _verify_manifest(
        PRIMARY,
        PRIMARY_MANIFEST,
        PRIMARY / "PRIMARY_FREEZE_SHA256.txt",
        data_directory=args.input_dir / "primary",
    )
    independent_manifest = _verify_manifest(
        INDEPENDENT,
        INDEPENDENT_MANIFEST,
        INDEPENDENT / "FROZEN_MANIFEST_SHA256.txt",
        data_directory=args.input_dir / "independent",
    )
    report = {
        "primary_manifest_sha256": sha256(PRIMARY_MANIFEST.read_bytes()).hexdigest(),
        "independent_manifest_sha256": sha256(INDEPENDENT_MANIFEST.read_bytes()).hexdigest(),
        "common_tagged_quotient": "Q0=1; layer tags retained; no other identities",
        "comparisons": {},
    }
    expected_maxima = {"A": 1, "B": 3, "C": 5}
    passed = True
    for depth in (3, 4):
        for unit in (False, True):
            scope = "UNIT" if unit else "TAGGED"
            primary_path = args.input_dir / "primary" / (
                f"H{depth}_UNIT_COEFFICIENTS.json"
                if unit
                else f"H{depth}_LAYER_TAGGED_COEFFICIENTS.json"
            )
            independent_path = args.input_dir / "independent" / f"H{depth}_{scope}_COEFFICIENT_MAP.json"
            primary, primary_maxima = _primary_map(primary_path, depth, unit)
            independent, independent_maxima = _independent_map(independent_path, depth, unit)
            comparison = {}
            for root in "ABC":
                keys = set(primary[root]) | set(independent[root])
                differences = [
                    {
                        "atoms": list(key),
                        "primary": str(primary[root].get(key, 0)),
                        "independent": str(independent[root].get(key, 0)),
                    }
                    for key in sorted(keys)
                    if primary[root].get(key, 0) != independent[root].get(key, 0)
                ]
                comparison[root] = {
                    "primary_terms": len(primary[root]),
                    "independent_terms": len(independent[root]),
                    "discrepancy_count": len(differences),
                    "first_discrepancies": differences[:20],
                    "primary_maximum_derivative": primary_maxima[root],
                    "independent_maximum_derivative": independent_maxima[root],
                }
                if differences or primary_maxima[root] != expected_maxima[root] or independent_maxima[root] != expected_maxima[root]:
                    passed = False
            report["comparisons"][f"H{depth}_{scope}"] = comparison

    # Cross-check that manifest term counts describe the parsed files.
    report["primary_manifest_term_counts"] = primary_manifest["term_counts"]
    report["independent_manifest_scope"] = independent_manifest["scope"]
    report["pass"] = passed
    args.output_dir.mkdir(parents=True, exist_ok=True)
    output = args.output_dir / "FROZEN_MAP_COMPARISON.json"
    output.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
    print(output.read_text())
    if not passed:
        raise SystemExit("frozen map comparison failed")


if __name__ == "__main__":
    main()

"""Evaluate the frozen unit-Gram normal forms for normalized sine."""

from __future__ import annotations

import json
from fractions import Fraction
from math import exp, pi, sqrt
from pathlib import Path
import re
import sys

import numpy as np
from numpy.polynomial.hermite import hermgauss

sys.path.insert(0, str(Path(__file__).resolve().parents[4]))
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)


ATOM = re.compile(r"M_\{([0-9]{6})\}")
HERE = Path(__file__).resolve().parent
PRIMARY = HERE.parent / "primary"


def evaluate_unit_artifact(path: Path, quadrature_order: int) -> dict[str, float]:
    nodes, weights = hermgauss(quadrature_order)
    gaussian = sqrt(2.0) * nodes
    weights = weights / sqrt(pi)
    normalization = sqrt((1.0 - exp(-2.0)) / 2.0)
    values: dict[str, float] = {}
    moments: dict[str, float] = {}

    def factor(token: str) -> float:
        token = token.strip()
        if token in values:
            return values[token]
        match = ATOM.fullmatch(token)
        if match:
            key = match.group(1)
            if key not in moments:
                integrand = np.ones_like(gaussian)
                for derivative, multiplicity_text in enumerate(key):
                    multiplicity = int(multiplicity_text)
                    if multiplicity:
                        derivative_value = (
                            np.sin(gaussian + derivative * pi / 2.0)
                            / normalization
                        )
                        integrand *= derivative_value**multiplicity
                moments[key] = float(weights @ integrand)
            return moments[key]
        return float(Fraction(token))

    for raw_line in path.read_text().splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        name, right_hand_side = (
            part.strip() for part in line.split("=", 1)
        )
        total = 0.0
        for summand in right_hand_side.split(" + "):
            product = 1.0
            for token in summand.split(" * "):
                product *= factor(token)
            total += product
        values[name] = total
    return {name: values[name] for name in ("A", "B", "C")}


def prediction(quadrature_order: int = 96) -> dict[str, object]:
    depths: dict[str, dict[str, float]] = {}
