#!/usr/bin/env python3
"""Exact H_0,...,H_19 and shifted-Hankel audit for depth-two identity."""

from __future__ import annotations

import hashlib
import json
from fractions import Fraction
from pathlib import Path
import sys

import sympy as sp


HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[3]))
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)
Q = Fraction


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def fraction_string(value: Fraction) -> str:
    return str(value.numerator) if value.denominator == 1 else f"{value.numerator}/{value.denominator}"


def ldl_leading_determinants(matrix: list[list[Fraction]]) -> tuple[list[Fraction], list[Fraction]]:
    size = len(matrix)
    lower = [[Q(0) for _ in range(size)] for _ in range(size)]
    diagonal = [Q(0) for _ in range(size)]
    determinants: list[Fraction] = []
    running = Q(1)
    for i in range(size):
        lower[i][i] = Q(1)
        diagonal[i] = matrix[i][i] - sum(
            lower[i][k] * lower[i][k] * diagonal[k]
            for k in range(i)
        )
        if not diagonal[i]:
            raise ArithmeticError(f"zero LDL pivot at {i}")
        for j in range(i + 1, size):
            numerator = matrix[j][i] - sum(
                lower[j][k] * lower[i][k] * diagonal[k]
                for k in range(i)
            )
            lower[j][i] = numerator / diagonal[i]
        running *= diagonal[i]
        determinants.append(running)
    return diagonal, determinants


def sympy_determinant(matrix: list[list[Fraction]], size: int) -> Fraction:
    submatrix = [
        [sp.Rational(value.numerator, value.denominator) for value in row[:size]]
        for row in matrix[:size]
    ]
    value = sp.Matrix(submatrix).det(method="domain-ge")
    return Q(int(value.p), int(value.q))


def audit_family(moments: list[Fraction], shift: int) -> dict[str, object]:
    size = 20
    matrix = [
        [moments[row + column + shift] for column in range(size)]
        for row in range(size)
    ]
    pivots, determinants = ldl_leading_determinants(matrix)
    checked_sizes = list(range(1, 7)) + [20]
    independent = {
        str(check_size): sympy_determinant(matrix, check_size)
        for check_size in checked_sizes
    }
    for check_size, value in independent.items():
        if value != determinants[int(check_size) - 1]:
            raise AssertionError(f"determinant routes disagree at size {check_size}")
    return {
        "shift": shift,
        "matrices": [f"H_{degree}" + ("_plus" if shift else "") for degree in range(20)],
        "ldl_pivots": [fraction_string(value) for value in pivots],
        "leading_determinants": [fraction_string(value) for value in determinants],
        "leading_determinant_signs": [
            "positive" if value > 0 else "zero" if value == 0 else "negative"
            for value in determinants
        ],
        "all_positive_definite": all(value > 0 for value in determinants),
        "independent_symbolic_checks": {
            f"size_{check_size}": fraction_string(value)
            for check_size, value in independent.items()
        },
        "independent_checks_agree": True,
    }


def main() -> int:
    args = PATHS.parse(inputs=True)
    INPUT = args.input_dir / "RESULTS.json"
    document = json.loads(INPUT.read_text())
    moments = [Q(value) for value in document["moments"]]
    if len(moments) != 40:
        raise AssertionError("expected exactly forty moments")
    ordinary = audit_family(moments, 0)
    shifted = audit_family(moments, 1)
    payload = {
        "format": "identity-depth2-hankel40-v1",
        "input_moments": ["mu_0", "...", "mu_39"],
        "moment_signs_all_positive": all(value > 0 for value in moments),
        "ordinary": ordinary,
        "shifted": shifted,
        "verdict": (
            "H_0_through_H_19_and_shifted_partners_are_all_positive_definite"
            if ordinary["all_positive_definite"] and shifted["all_positive_definite"]
            else "at_least_one_accessible_Hankel_matrix_is_not_positive_definite"
        ),
        "claim_boundary": (
            "Exact finite forty-moment compatibility only; no all-order sequence, "
            "measure, or convergence claim."
        ),
        "sha256": {
            "input": sha256(INPUT),
            "protocol": sha256(HERE / "HANKEL40_PROTOCOL.md"),
            "source": sha256(Path(__file__)),
        },
    }
    args.output_dir.mkdir(parents=True, exist_ok=True)
    output = args.output_dir / "HANKEL40_RESULTS.json"
    output.write_text(json.dumps(payload, indent=2) + "\n")
    print(json.dumps({
        "output": str(output),
        "verdict": payload["verdict"],
        "ordinary_terminal_sign": ordinary["leading_determinant_signs"][-1],
        "shifted_terminal_sign": shifted["leading_determinant_signs"][-1],
        "ordinary_terminal_digits": len(ordinary["leading_determinants"][-1]),
        "shifted_terminal_digits": len(shifted["leading_determinants"][-1]),
    }, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Exact long-jet production and precommitted closure search for H=2 identity."""

from __future__ import annotations

import hashlib
import json
import math
import sys
import time
from fractions import Fraction
from functools import reduce
from pathlib import Path

import sympy as sp


HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[3]))
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)
PARENT = HERE.parent
sys.path.insert(0, str(PARENT))

from identity_exact_jet import depth2_derivative, depth2_taylor, validate  # noqa: E402
from identity_stieltjes_audit import (  # noqa: E402
    fraction_string,
    load_reversion_route,
    moments_from_triangular_identity,
)


Q = Fraction
MAX_ORDER = 81
DISCOVERY_LAST = 24
HOLDOUT_LAST = 39


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def multiply(left: list[Fraction], right: list[Fraction], degree: int) -> list[Fraction]:
    result = [Q(0) for _ in range(degree + 1)]
    for i, a in enumerate(left):
        if i > degree or not a:
            continue
        for j, b in enumerate(right):
            if i + j > degree:
                break
            if b:
                result[i + j] += a * b
    return result


def powers(series: list[Fraction], max_power: int, degree: int) -> list[list[Fraction]]:
    result = [[Q(1)] + [Q(0) for _ in range(degree)]]
    padded = series[: degree + 1] + [Q(0)] * max(0, degree + 1 - len(series))
    for _ in range(max_power):
        result.append(multiply(result[-1], padded, degree))
    return result


def primitive_integer_vector(vector: sp.Matrix) -> tuple[int, ...]:
    rationals = [sp.Rational(value) for value in vector]
    denominator_lcm = math.lcm(*(int(value.q) for value in rationals))
    integers = [int(value * denominator_lcm) for value in rationals]
    common = reduce(math.gcd, (abs(value) for value in integers if value), 0)
    if not common:
        raise ArithmeticError("zero null vector")
    integers = [value // common for value in integers]
    first = next(value for value in integers if value)
    if first < 0:
        integers = [-value for value in integers]
    return tuple(integers)


def algebraic_candidates(moments: list[Fraction]) -> list[dict[str, object]]:
    max_degree = HOLDOUT_LAST
    moment_powers = powers(moments, 4, max_degree)
    candidates: list[dict[str, object]] = []
    seen: set[tuple[int, ...]] = set()
    q, z = sp.symbols("q z")

    boxes = []
    for degree_z in range(1, 5):
        for degree_q in range(0, 7):
            count = (degree_q + 1) * (degree_z + 1)
            if count <= DISCOVERY_LAST + 1:
                boxes.append((count, degree_z, degree_q))

    for _, degree_z, degree_q in sorted(boxes):
        terms = [
            (i, j)
            for i in range(degree_q + 1)
            for j in range(degree_z + 1)
        ]
        rows = []
        for order in range(DISCOVERY_LAST + 1):
            rows.append([
                sp.Rational(moment_powers[j][order - i].numerator,
                            moment_powers[j][order - i].denominator)
                if order >= i else sp.Integer(0)
                for i, j in terms
            ])
        nullspace = sp.Matrix(rows).nullspace()
        if len(nullspace) != 1:
            continue
        vector = primitive_integer_vector(nullspace[0])
        if vector in seen:
            continue
        nonzero_terms = [terms[index] for index, value in enumerate(vector) if value]
        if min(i for i, _ in nonzero_terms) != 0:
            continue
        if max(i for i, _ in nonzero_terms) != degree_q:
            continue
        if max(j for _, j in nonzero_terms) != degree_z:
            continue

        residuals: list[Fraction] = []
        for order in range(HOLDOUT_LAST + 1):
            value = Q(0)
            for coefficient, (i, j) in zip(vector, terms):
                if coefficient and order >= i:
                    value += coefficient * moment_powers[j][order - i]
            residuals.append(value)
        discovery_pass = all(value == 0 for value in residuals[: DISCOVERY_LAST + 1])
        holdout = residuals[DISCOVERY_LAST + 1 : HOLDOUT_LAST + 1]
        if not discovery_pass or not all(value == 0 for value in holdout):
            continue

        expression = sum(
            coefficient * q**i * z**j
            for coefficient, (i, j) in zip(vector, terms)
        )
        primitive = sp.Poly(expression, q, z, domain=sp.ZZ).primitive()[1]
        canonical = tuple(int(value) for value in primitive.coeffs())
        if canonical in seen:
            continue
        seen.add(vector)
        seen.add(canonical)
        candidates.append({
            "degree_q": degree_q,
            "degree_M": degree_z,
            "coefficient_count": len(terms),
            "polynomial": str(sp.factor(expression)),
            "terms": [
                {"q_power": i, "M_power": j, "coefficient": coefficient}
                for coefficient, (i, j) in zip(vector, terms)
                if coefficient
            ],
            "discovery_coefficients_zero": DISCOVERY_LAST + 1,
            "held_out_coefficients_zero": len(holdout),
            "held_out_exact_pass": True,
        })
    return candidates


def recurrence_candidates(moments: list[Fraction]) -> list[dict[str, object]]:
    candidates: list[dict[str, object]] = []
    seen: set[tuple[int, ...]] = set()
    r_symbol = sp.symbols("r")
    boxes = []
    for order in range(1, 5):
        for degree in range(0, 5):
            count = (order + 1) * (degree + 1)
            if count <= DISCOVERY_LAST + 1:
                boxes.append((count, order, degree))

    for _, recurrence_order, polynomial_degree in sorted(boxes):
        terms = [
            (shift, degree)
            for shift in range(recurrence_order + 1)
            for degree in range(polynomial_degree + 1)
        ]
        discovery_rows = range(0, DISCOVERY_LAST - recurrence_order + 1)
        rows = [
            [
                sp.Rational(moments[index + shift].numerator,
                            moments[index + shift].denominator)
                * index**degree
                for shift, degree in terms
            ]
            for index in discovery_rows
        ]
        nullspace = sp.Matrix(rows).nullspace()
        if len(nullspace) != 1:
            continue
        vector = primitive_integer_vector(nullspace[0])
        if vector in seen:
            continue
        if not any(
            coefficient
            for coefficient, (shift, _) in zip(vector, terms)
            if shift == recurrence_order
        ):
            continue
        if max(
            degree for coefficient, (_, degree) in zip(vector, terms) if coefficient
        ) != polynomial_degree:
            continue

        residuals = []
        for index in range(0, HOLDOUT_LAST - recurrence_order + 1):
            residuals.append(sum(
                Q(coefficient) * index**degree * moments[index + shift]
                for coefficient, (shift, degree) in zip(vector, terms)
            ))
        discovery_count = DISCOVERY_LAST - recurrence_order + 1
        holdout = residuals[discovery_count:]
        if not all(value == 0 for value in residuals[:discovery_count]):
            continue
        if not holdout or not all(value == 0 for value in holdout):
            continue

        polynomials = []
        for shift in range(recurrence_order + 1):
            expression = sum(
                coefficient * r_symbol**degree
                for coefficient, (candidate_shift, degree) in zip(vector, terms)
                if candidate_shift == shift
            )
            polynomials.append(sp.Poly(expression, r_symbol, domain=sp.ZZ))
        common = reduce(sp.gcd, polynomials)
        if common.degree() > 0:
            polynomials = [sp.exquo(poly, common) for poly in polynomials]
        canonical = tuple(
            int(coefficient)
            for poly in polynomials
            for coefficient in poly.all_coeffs()
        )
        if canonical in seen:
            continue
        seen.add(vector)
        seen.add(canonical)
        candidates.append({
            "order": recurrence_order,
            "polynomial_degree": polynomial_degree,
            "coefficient_count": len(terms),
            "polynomials_by_shift": [str(poly.as_expr()) for poly in polynomials],
            "meaning": "sum_j p_j(r)*mu_(r+j)=0",
            "discovery_equations_zero": discovery_count,
            "held_out_equations_zero": len(holdout),
            "held_out_exact_pass": True,
        })
    return candidates


def main() -> int:
    args = PATHS.parse()
    started = time.perf_counter()
    taylor = depth2_taylor(MAX_ORDER)
    derivative = depth2_derivative(MAX_ORDER)
    validation = validate([taylor, derivative], MAX_ORDER)
    if taylor.derivatives != derivative.derivatives:
        raise AssertionError("the two exact jet routes disagree")

    odd = {
        order: int(taylor.derivatives[order])
        for order in range(1, MAX_ORDER + 1, 2)
    }
    baseline_a, moments_a = moments_from_triangular_identity(odd)
    reversion = load_reversion_route()
    baseline_b, moments_b = reversion(odd)
    if baseline_a != baseline_b or moments_a != moments_b:
        raise AssertionError("the two exact moment routes disagree")
    if len(moments_a) != HOLDOUT_LAST + 1:
        raise AssertionError("order 81 must determine mu_0 through mu_39")

    moment_list = list(moments_a)
    algebraic = algebraic_candidates(moment_list)
    recurrences = recurrence_candidates(moment_list)
    payload = {
        "format": "identity-depth2-all-order-search-v1",
        "model": "one-input equal-width identity activation, two hidden layers",
        "max_feature_derivative_order": MAX_ORDER,
        "derivatives": [fraction_string(value) for value in taylor.derivatives],
        "kernel_baseline": fraction_string(baseline_a),
        "moments": [fraction_string(value) for value in moment_list],
        "discovery_moments": [0, DISCOVERY_LAST],
        "held_out_moments": [DISCOVERY_LAST + 1, HOLDOUT_LAST],
        "algebraic_ogf_candidates": algebraic,
        "p_recursive_candidates": recurrences,
        "validation": {
            **validation,
            "moment_routes_agree": True,
            "candidate_claim_level": "held-out exact coefficient identity only",
        },
        "elapsed_seconds": {
            "taylor": taylor.elapsed_seconds,
            "derivative": derivative.elapsed_seconds,
            "total": time.perf_counter() - started,
        },
        "sha256": {
            "protocol": sha256(HERE / "PROTOCOL.md"),
            "jet_source": sha256(PARENT / "identity_exact_jet.py"),
            "search_source": sha256(Path(__file__)),
        },
        "claim_boundary": (
            "A held-out pass is conjectural until independently derived; "
            "failure finds no formula only in the frozen bounded classes."
        ),
    }
    args.output_dir.mkdir(parents=True, exist_ok=True)
    output = args.output_dir / "RESULTS.json"
    output.write_text(json.dumps(payload, indent=2) + "\n")
    print(json.dumps({
        "output": str(output),
        "elapsed_seconds": payload["elapsed_seconds"],
        "algebraic_candidate_count": len(algebraic),
        "recurrence_candidate_count": len(recurrences),
        "last_derivative": payload["derivatives"][-1],
        "last_moment": payload["moments"][-1],
    }, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Independent Wishart/rank-one spectral closure for depth-two identity."""

from __future__ import annotations

import hashlib
import json
import math
import sys
from fractions import Fraction
from pathlib import Path
import sys


HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[3]))
from studies.repository_refactor_2026_09_09.output_paths import StudyPaths

PATHS = StudyPaths(__file__)
PARENT = HERE.parent
sys.path.insert(0, str(PARENT))

from identity_stieltjes_audit import (  # noqa: E402
    fraction_string,
    moments_from_triangular_identity,
)


Q = Fraction
MAX_FEATURE_ORDER = 81
MAX_R_ORDER = MAX_FEATURE_ORDER + 1
Polynomial = list[Fraction]


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def trim(polynomial: Polynomial) -> Polynomial:
    result = list(polynomial)
    while len(result) > 1 and not result[-1]:
        result.pop()
    return result


def add(left: Polynomial, right: Polynomial) -> Polynomial:
    size = max(len(left), len(right))
    return trim([
        (left[index] if index < len(left) else Q(0))
        + (right[index] if index < len(right) else Q(0))
        for index in range(size)
    ])


def scale(polynomial: Polynomial, coefficient: Fraction | int) -> Polynomial:
    coefficient = Q(coefficient)
    return trim([coefficient * value for value in polynomial])


def multiply(left: Polynomial, right: Polynomial) -> Polynomial:
    result = [Q(0) for _ in range(len(left) + len(right) - 1)]
    for i, left_value in enumerate(left):
        if not left_value:
            continue
        for j, right_value in enumerate(right):
            if right_value:
                result[i + j] += left_value * right_value
    return trim(result)


def lambda_times(polynomial: Polynomial) -> Polynomial:
    return [Q(0)] + list(polynomial)


def catalan(index: int) -> int:
    return math.comb(2 * index, index) // (index + 1)


def inverse_series(series: list[Fraction], degree: int) -> list[Fraction]:
    if not series or not series[0]:
        raise ArithmeticError("series is not invertible")
    result = [Q(0) for _ in range(degree + 1)]
    result[0] = 1 / series[0]
    for order in range(1, degree + 1):
        result[order] = -sum(
            series[index] * result[order - index]
            for index in range(1, min(order, len(series) - 1) + 1)
        ) / series[0]
    return result


def initial_spectral_moments(max_degree: int) -> tuple[list[Fraction], list[Fraction]]:
    """Moments of rho_x and rho_v derived from MP(1), not feature jets.

    If m(w)=sum C_k w^(k+1) is the MP resolvent at infinity, the rank-one
    Sherman--Morrison identity gives g_x=m/(1+m).  The velocity measure is
    the size-biased MP law, so its kth moment is C_(k+1).
    """

    degree = max_degree + 1
    mp = [Q(0)] + [Q(catalan(index)) for index in range(max_degree + 1)]
    denominator = list(mp)
    denominator[0] += 1
    inverse = inverse_series(denominator, degree)
    product = [Q(0) for _ in range(degree + 1)]
    for i, left in enumerate(mp):
        for j, right in enumerate(inverse):
            if i + j <= degree:
                product[i + j] += left * right
    rho_x = [product[index + 1] for index in range(max_degree + 1)]
    rho_v = [Q(catalan(index + 1)) for index in range(max_degree + 1)]
    return rho_x, rho_v


def integrate(polynomial: Polynomial, moments: list[Fraction]) -> Fraction:
    if len(polynomial) > len(moments):
        raise ArithmeticError("not enough spectral moments")
    return sum(
        coefficient * moments[degree]
        for degree, coefficient in enumerate(polynomial)
    )


def spectral_fixed_point(max_r_order: int) -> tuple[list[Fraction], list[Polynomial], list[Polynomial]]:
    spectral_degree = max_r_order // 2 + 2
    rho_x, rho_v = initial_spectral_moments(spectral_degree)
    a: list[Polynomial] = [[Q(1)], [Q(0)]]
    b: list[Polynomial] = [[Q(0)], [Q(1)]]
    r: list[Fraction] = [Q(1), Q(0)]

    for degree in range(2, max_r_order + 1):
        prior = degree - 2
        rhs_a = lambda_times(a[prior])
        rhs_b = lambda_times(b[prior])
        potential_a = [Q(0)]
        potential_b = [Q(0)]
        for left in range(prior + 1):
            potential_a = add(potential_a, scale(a[prior - left], r[left]))
            potential_b = add(potential_b, scale(b[prior - left], r[left]))
        denominator = degree * (degree - 1)
        a.append(scale(add(rhs_a, scale(potential_a, 2)), Q(1, denominator)))
        b.append(scale(add(rhs_b, scale(potential_b, 2)), Q(1, denominator)))

        norm_coefficient_a = [Q(0)]
        norm_coefficient_b = [Q(0)]
        for left in range(degree + 1):
            norm_coefficient_a = add(
                norm_coefficient_a, multiply(a[left], a[degree - left])
            )
            norm_coefficient_b = add(
                norm_coefficient_b, multiply(b[left], b[degree - left])
            )
        r.append(
            integrate(norm_coefficient_a, rho_x)
            + integrate(norm_coefficient_b, rho_v)
        )
    return r, a, b


def main() -> int:
    args = PATHS.parse(inputs=True)
    accepted_path = args.input_dir / "RESULTS.json"
    accepted = json.loads(accepted_path.read_text())
    r, a, b = spectral_fixed_point(MAX_R_ORDER)
    derivatives = [
        Q(math.factorial(order + 1), 2) * r[order + 1]
        for order in range(MAX_FEATURE_ORDER + 1)
    ]
    accepted_derivatives = [Q(value) for value in accepted["derivatives"]]
    if derivatives != accepted_derivatives:
        mismatch = next(
            index for index, pair in enumerate(zip(derivatives, accepted_derivatives))
            if pair[0] != pair[1]
        )
        raise AssertionError(f"spectral closure first differs at F^{mismatch}")
    odd = {
        order: int(derivatives[order])
        for order in range(1, MAX_FEATURE_ORDER + 1, 2)
    }
    baseline, moments = moments_from_triangular_identity(odd)
    accepted_moments = tuple(Q(value) for value in accepted["moments"])
    if moments != accepted_moments:
        raise AssertionError("spectral closure output moments differ")

    rho_x, rho_v = initial_spectral_moments(12)
    payload = {
        "format": "identity-depth2-spectral-closure-v1",
        "finite_width_invariant": "C=B*B^T-x*x^T",
        "vector_equation": "x''=(C+||x||^2+||y||^2)*x",
        "width_limit_balance": "||x||^2=||y||^2=r",
        "spectral_measures": {
            "MP_density": "sqrt((4-lambda)/lambda)/(2*pi) on (0,4)",
            "rho_x_resolvent": "g_x=m_MP/(1+m_MP)",
            "rho_x_explicit": "(3/4)*delta_(-1/2) + sqrt(lambda*(4-lambda))/(2*pi*(1+2*lambda)) on (0,4)",
            "rho_v_explicit": "sqrt(lambda*(4-lambda))/(2*pi) on (0,4)",
            "rho_x_moments_0_through_12": [fraction_string(value) for value in rho_x],
            "rho_v_moments_0_through_12": [fraction_string(value) for value in rho_v],
        },
        "closed_fixed_point": {
            "mode_equations": [
                "a_lambda''=(lambda+2*r)*a_lambda, a_lambda(0)=1, a_lambda'(0)=0",
                "b_lambda''=(lambda+2*r)*b_lambda, b_lambda(0)=0, b_lambda'(0)=1",
            ],
            "self_consistency": "r=int a_lambda^2 d rho_x + int b_lambda^2 d rho_v",
            "feature": "F=r'/2",
        },
        "validation": {
            "derivatives_match_independent_gaussian_program_through_81": True,
            "moments_mu_0_through_39_match": True,
            "kernel_baseline": fraction_string(baseline),
            "max_a_polynomial_support": max(len(value) for value in a),
            "max_b_polynomial_support": max(len(value) for value in b),
        },
        "classification": (
            "exact all-fixed-order formal spectral closure, but not an elementary "
            "closed form for F or K and not an all-order Stieltjes proof"
        ),
        "sha256": {
            "accepted_comparison_input": sha256(accepted_path),
            "protocol": sha256(HERE / "SPECTRAL_CLOSURE_PROTOCOL.md"),
            "source": sha256(Path(__file__)),
        },
    }
    args.output_dir.mkdir(parents=True, exist_ok=True)
    output = args.output_dir / "SPECTRAL_CLOSURE_RESULTS.json"
    output.write_text(json.dumps(payload, indent=2) + "\n")
    print(json.dumps({
        "output": str(output),
        "derivative_match_through": MAX_FEATURE_ORDER,
        "moment_match_through": 39,
        "rho_x_prefix": payload["spectral_measures"]["rho_x_moments_0_through_12"],
    }, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

